package org.springframework.web.method; import java.lang.annotation.Annotation; import java.lang.reflect.Method; public class HandlerMethod {private final Object bean;private final Method method;public HandlerMethod(Object b,Method m){bean=b;method=m;}public <A extends Annotation>A getMethodAnnotation(Class<A> c){return method.getAnnotation(c);}public Class<?> getBeanType(){return bean.getClass();}}
